-- The 2026-11 release's new records, in one migration (operator, 2026-11-12). Never applied anywhere before this
-- release; regenerated from ~/3shub-docs (epc_harvest_2026-11, web_harvest_2026-11) until it ships.

-- The Australian-delivered 3000GTs (VINs JMF..., Mitsubishi Australia): their own Model key and market, so they never
-- shift a North American, Japanese or export count. None is in a Mitsubishi factory record we hold or in the online
-- catalogues (card 388); the cars come from owner listings, each with its own Provenance.

-- Known missing VIN ranges (card 388): serials missing from every record we hold, shown red in the stats page's
-- search so owners can send their VIN tag. US: missing from NA9199 + CAPS 2004 (000101 and up; 000001-000100 are
-- pre-production and left out). Australia: of the 117 delivered, the serials no listing or web page has given.
CREATE TABLE MissingRange (
	ID INTEGER PRIMARY KEY {autoincrement},
	Market VARCHAR(10) NOT NULL,
	ModelYear CHAR(2) NOT NULL,
	VinPattern VARCHAR(17) NOT NULL,
	FirstSerial CHAR(6) NOT NULL,
	LastSerial CHAR(6) NOT NULL,
	Note VARCHAR(200) NOT NULL DEFAULT ''
);
CREATE INDEX idx_missing_range ON MissingRange (Market, ModelYear, FirstSerial);
